export function questionsFor(title: string): Question[] {
  return (bank[title] ?? []).map(([text, answer, wrong, explain], i) => {
    const options = [...new Set([answer, ...wrong])];
    const offset = i % options.length;
    const shuffled = [...options.slice(offset), ...options.slice(0, offset)];
    return { type: "mcq", q: text, options: shuffled, answer: shuffled.indexOf(answer), explain };
  });
}